<?php
require_once __DIR__.'/../config/bootstrap.php';require_admin();$id=(int)($_GET['id']??0);$s=db()->prepare('SELECT * FROM orders WHERE id=?');$s->execute([$id]);$order=$s->fetch();if(!$order){http_response_code(404);exit('Order not found');}
$s=db()->prepare('SELECT * FROM order_items WHERE order_id=? ORDER BY id');$s->execute([$id]);$items=$s->fetchAll();$s=db()->prepare('SELECT old_status,new_status,note,created_at FROM order_status_history WHERE order_id=? ORDER BY id DESC');$s->execute([$id]);$history=$s->fetchAll();
$pageTitle='Order details — Ikki';require __DIR__.'/../includes/header.php';?>
<div class="admin-shell"><h1 class="page-title">Order · <?=e($order['order_number'])?></h1><nav class="admin-nav"><a href="/admin/">Overview</a><a href="/admin/orders.php">Orders</a><a href="/admin/customers.php">Customers</a></nav>
<div class="stats"><div class="stat"><span class="muted">Order status</span><b style="font-size:20px"><?=e($order['order_status'])?></b></div><div class="stat"><span class="muted">Payment</span><b style="font-size:20px"><?=e($order['payment_method'])?> · <?=e($order['payment_status'])?></b></div><div class="stat"><span class="muted">Grand total</span><b><?=money($order['grand_total'])?></b></div><div class="stat"><span class="muted">Placed</span><b style="font-size:18px"><?=e($order['created_at'])?></b></div></div>
<h2 style="font:30px var(--serif);margin-top:35px">Customer and delivery</h2><p><strong><?=e($order['customer_name'])?></strong><br><?=e($order['customer_phone'])?><br><?=e($order['customer_email']??'')?><br><?=e($order['delivery_address'])?><br><?=e($order['city'])?>, <?=e($order['province'])?> <?=e($order['postal_code']??'')?></p><?php if($order['delivery_instructions']):?><p class="muted">Delivery instructions: <?=e($order['delivery_instructions'])?></p><?php endif;?>
<h2 style="font:30px var(--serif);margin-top:35px">Items</h2><div style="overflow-x:auto"><table class="cart-table"><thead><tr><th>Product</th><th>Variant</th><th>SKU</th><th>Unit price</th><th>Qty</th><th>Line total</th></tr></thead><tbody><?php foreach($items as $item):?><tr><td><?=e($item['product_name_snapshot'])?></td><td><?=e($item['variant_name_snapshot'])?></td><td><?=e($item['sku_snapshot'])?></td><td><?=money($item['unit_price'])?></td><td><?=(int)$item['quantity']?></td><td><?=money($item['line_total'])?></td></tr><?php endforeach;?></tbody></table></div><p>Subtotal: <?=money($order['subtotal'])?><br>Delivery: <?=money($order['delivery_fee'])?><br><strong>Total: <?=money($order['grand_total'])?></strong></p>
<h2 style="font:30px var(--serif);margin-top:35px">Status history</h2><ol><?php foreach($history as $event):?><li><strong><?=e($event['new_status'])?></strong> — <?=e($event['created_at'])?><?php if($event['old_status']):?><span class="muted"> (from <?=e($event['old_status'])?>)</span><?php endif;?><?php if($event['note']):?><p class="muted"><?=e($event['note'])?></p><?php endif;?></li><?php endforeach;?></ol></div><?php require __DIR__.'/../includes/footer.php';?>